/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var isArrayArray = require( '@stdlib/assert/is-array-array' );
var isNumberArray = require( '@stdlib/assert/is-number-array' );
var isString = require( '@stdlib/assert/is-string' );
var isObjectArray = require( '@stdlib/assert/is-object-array' );
var isEmptyArray = require( '@stdlib/assert/is-empty-array' );
var format = require( '@stdlib/string/format' );
var everyBy2 = require( '@stdlib/plot/unicode/base/lib/every_by2.js' );


// FUNCTIONS //

// MAIN //

/**
* Sets the axis data.
*
* @private
* @param {String} value - boolean indicating whether to automatically re-render on a `change` event
* @throws {TypeError} must be a boolean
*/
function set( value ) {
	if ( !isString( value ) ) {
		throw new TypeError( format( 'invalid assignment. string is expected. Value: `%s`.', 'axis-data', value ) );
	}
	if ( value != 'linear' || value != 'original' || value != 'logirithemic'  ) {
		throw new TypeError( format( 'invalid assignment. value must be linear, original or logirithmeic. Value: `%s`.', 'x-axis-tics-scale-type', value ) );
	}
	if ( this._axisDataObjs[ 1 ].scaleType !== value ) {
		this._axisDataObjs[ 1 ].scaleType = value
		if ( !this._quite ) {
			this.emit( 'change' );
		}
	}

}


// EXPORTS //

module.exports = set;
